"""Native evaluation where every control is generated by the StyleGAN actor."""
import os
os.environ.setdefault('MUJOCO_GL','egl');os.environ.setdefault('OMP_NUM_THREADS','1');os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import argparse,json,hashlib,time
from pathlib import Path
import numpy as np
import torch
from cube_addons.env import make_env,close_env
from cube_composition.evaluate import load_cases,summarize
from cube_composition.rollout import rollout
from .actor_policy import Bank,ActorPolicy


def main():
    p=argparse.ArgumentParser();p.add_argument('--tasks',required=True);p.add_argument('--out',required=True);p.add_argument('--count',type=int,default=16)
    p.add_argument('--keepout',default='cube_agreement_artifacts/decoders/keepout_s42/best.pt');p.add_argument('--waypoint',default='cube_agreement_artifacts/decoders/waypoint_s42/best.pt');p.add_argument('--actor',default='cube_agreement_artifacts/action_adapter_v1/best.pt')
    p.add_argument('--device',default='cuda',choices=['cpu','cuda']);p.add_argument('--method',choices=['agreement','multiscale','local_action','single_keepout','single_waypoint'],default='agreement');p.add_argument('--family',choices=['keepout','waypoint'],default='waypoint');p.add_argument('--steps',type=int,default=120);p.add_argument('--starts',type=int,default=12);p.add_argument('--seed',type=int,default=42);p.add_argument('--execute',type=int,choices=[1,2,4,8,16],default=4);p.add_argument('--action-steps',type=int,default=20);p.add_argument('--path-weight',type=float,default=1.);p.add_argument('--continuity-weight',type=float,default=.001);p.add_argument('--action-interval',type=int,default=1);p.add_argument('--action-starts',type=int,default=0)
    args=p.parse_args();torch.set_num_threads(2);bank=Bank(args.keepout,args.waypoint,args.actor,device=args.device);out=Path(args.out);out.mkdir(parents=True,exist_ok=True);rows=[];planning=[];env=make_env();started=time.perf_counter()
    config={'args':vars(args),'frozen_files':{v:hashlib.sha256(Path(v).read_bytes()).hexdigest() for v in [args.keepout,args.waypoint,args.actor,'cube/artifacts/final/base_policy.pt']},'task_sha256':hashlib.sha256(Path(args.tasks).read_bytes()).hexdigest(),'source_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in Path(__file__).parent.glob('*.py')},'mechanism':'Frozen independent neural route decoders, latent-only route agreement, and retrained original StyleGAN action adapter for ALL robot controls; generic path cursor. No identified steering, online teacher, geometric correction, native task-cost candidate selection, or direct action optimization.'}
    config['agreement_objective']={'agreement':'Whole-route normalized MSE plus generic latent prior','local_action':'Raw predicted 16x5 action-chunk MSE plus generic latent prior and temporal code-continuity regularization. NO whole-route agreement loss.','multiscale':'Raw predicted 16x5 action-chunk MSE plus normalized whole-route MSE, generic prior and temporal code-continuity regularization.'}.get(args.method,'Independent single-skill latent; no joint agreement optimization')
    if args.method=='local_action':config['mechanism']=config['mechanism'].replace('latent-only route agreement','latent-only action-chunk agreement')
    elif args.method=='multiscale':config['mechanism']=config['mechanism'].replace('latent-only route agreement','latent-only action and route agreement')
    (out/'config.json').write_text(json.dumps(config,indent=2)+'\n')
    try:
        for i,case in enumerate(load_cases(args.tasks,args.count)):
            controller=ActorPolicy(bank,case,args.method,args.family,args.steps,args.starts,args.seed+9973*i,args.execute,args.action_steps,args.path_weight,args.continuity_weight,args.action_interval,args.action_starts)
            row,trace,plans=rollout(env,None,case,planner_override=controller,execute=1)
            held=trace['held'];poses=trace['poses'];near=np.linalg.norm(poses[1:-1,3:5]-case['goal'][:2],axis=1)<.06
            transitions=np.flatnonzero(held[:-1]&~held[1:]&near);height=float(poses[transitions[-1]+1,5]) if row['released_success'] and len(transitions) else None
            row.update(context=i,last_supported_release_height_m=height,controlled_release_success=bool(row['success'] and height is not None and height<=.065))
            if args.method.startswith('single_'):
                own=args.method.removeprefix('single_');row['own_full_skill_success']=bool(row['released_success'] and row[own+'_satisfied'] and not row['dropped'] and not row['robot_table_contact_in_transport'])
                row['controlled_own_full_skill_success']=bool(row['own_full_skill_success'] and height is not None and height<=.065)
            np.savez_compressed(out/f'rollout_{i:04d}.npz',**case,**trace,reference_path=controller.path)
            rows.append(row);planning.append(plans);(out/'records.json').write_text(json.dumps(rows,indent=2)+'\n');(out/'planning.json').write_text(json.dumps(planning,indent=2)+'\n');print('EPISODE',i,'joint',row['success'],'controlled',row['controlled_release_success'],'goal',row['released_success'],'K',row['keepout_satisfied'],'W',row['waypoint_satisfied'],flush=True)
        result=summarize(rows,planning);result['controlled_release_success']=float(np.mean([r['controlled_release_success'] for r in rows]));result['elapsed_seconds']=time.perf_counter()-started
        (out/'summary.json').write_text(json.dumps(result,indent=2)+'\n');bank.assert_frozen();(out/'DONE.json').write_text(json.dumps({'complete':True,'episodes':len(rows),'weights_frozen':True}));print(json.dumps(result,indent=2),flush=True)
    finally:close_env(env)


if __name__=='__main__':main()
